        "一方、華北では五胡十六国の混乱を統一する国が現れた。鮮卑を統一した拓跋珪【道武帝】が平城を都に北魏を建国し、遊牧民の部族制を解体しながら、ちょっとずつ中国の制度を取り入れて漢民族への支配も拡大した。こうして強くなった北魏は、439年に太武帝が華北を統一したよ。これで中国には北と南に二人の皇帝が立つことになった。これが南北朝時代だよ。"
