      "title": "仏教の発展と廃仏",
      "body": [
        "ただ、この時代の中国では仏教と道教が対立していたよ。仏教は後漢の初期にはすでに中国に伝わり、五胡十六国時代には仏図澄【ブドチンガ】が洛陽で布教に活躍したり、鳩摩羅什【クマラジーヴァ】が長安で仏典を漢訳したりして、華北で仏教が拡大していた。このあと、仏図澄の弟子だった道安が戒律を整備し、その弟子の慧遠は浄土宗のもととなった白蓮社をつくっている。さらに東晋時代の僧法顕は、長安から陸路を通ってグプタ朝時代のインドに行き、仏典を集めたのちに海路で帰国した。このときの旅行記が『仏国記』だね。",
        "こうして、少しずつ教団の形が整ってきた仏教に対抗して、寇謙之は五斗米道【天師道】をもとに、神仙思想や老荘思想を取り込み、仏教の儀礼などの影響を受けて道教教団（新天師道）を形成し、仏教に対抗するために、太武帝に接近した。道教を国教にした太武帝は仏教を弾圧したんだよ。この太武帝の廃仏が、中国史上有名な「三武一宗の法難」の最初だよ。"
      ],
