      "id": "c03-l10-p02-004",
      "title": "均田制と官人永業田",
      "body": [
        "土地制度にも、貴族勢力が残った原因があるよ。",
        "農民支配は隋を継承して、均田制を基礎に租庸調と府兵制を組み合わせて国家が農民を直接支配する体制を完成したよ。まず、<span class=\"source-bold\">均田制</span>では土地国有を原則に、男性（丁男・中男）に<span class=\"source-bold\">口分田80畝</span>（死後返還するのがタテマエ）と<span class=\"source-bold\">永業田20畝</span>（世襲できるよ）を支給した。そして、隋の時代を引き継いで、妻・奴婢・耕牛への給田は停止したから、貴族や地主の大土地所有は抑えられそうに見えるよね。でも、この制度にはウラがある😨。官僚には<span class=\"source-bold\">官人永業田</span>、要は役人にボーナスが支給されて、高級官僚だとなんと口分田の100倍😨。つまり、高級官僚になれば大土地所有者のままだったから、貴族の勢力はほとんど残るんだ。"
      ],
