      "id": "c03-l10-p03-001",
      "title": "唐と東突厥の対立",
      "body": [
        "隋の初めに東西に分裂したトルコ系遊牧民の<span class=\"source-bold\">突厥</span>は、7世紀初めには隋末の混乱に乗じて勢力を拡大し、<span class=\"source-bold\">東突厥</span>は中国内部に進出した。突厥がすごく強かったから、唐も突厥の援助を受けて建国した。それが逆転するのが太宗【李世民】時代だよ。",
        "李世民が中国をほとんど統一すると、華北では東突厥と唐が対立する状況になった。李世民兄弟の対立をチャンスと考えた東突厥は、10万の騎馬集団で唐に攻め込んできた。しかし、皇帝に即位した直後の太宗は、自ら軍を率いて東突厥を破って滅ぼした。これで、突厥は一時滅亡したよ（突厥第一帝国）。唐が突厥を破ると、「こりゃ唐には勝てん😨」と思った突厥支配下の遊牧民は、太宗に遊牧諸民族の上に立つ「<span class=\"source-bold\">天可汗</span>」の称号を贈ったんだ。"
      ],
