      "id": "c03-l10-p03-003",
      "title": "朝鮮半島の三国と唐",
      "body": [
        "朝鮮半島で唐が頭を悩ましていたのは高句麗だよ。当時、朝鮮半島では南の<span class=\"source-bold\">百済</span>と<span class=\"source-bold\">新羅</span>が加耶【伽耶】諸国をめぐって争い、新羅が加耶を手に入れると、北方の<span class=\"source-bold\">高句麗</span>とあわせて三国時代になった。3国はそれぞれ中国の北朝・南朝への朝貢や倭（日本）との関係を通じて他の2国を牽制したんだけど、隋が中国を統一すると3国とも隋に朝貢したので、いったん朝鮮半島は落ち着いたように見えた。ただ、高句麗が隋の遠征を撃退して、しかも隋が滅んじゃった😨。唐にとっては「高句麗をどう抑えるか」が大問題だったんだ。"
      ],
