      "id": "c03-l10-p04-003",
      "title": "韋后の失脚と玄宗",
      "body": [
        "ただ、さすがの武后も年齢には勝てず、クーデタで幽閉されて息子の中宗が再び皇帝に即位した。でも、中宗も頼りない男だった😨。そしたら、権力欲のかたまりだった奥さんの韋后が、「ワタシも則天武后のように権力を握りたい！」と、邪魔になった中宗を毒殺して権力を握ろうとしたんだ。でも、韋后は則天武后ほど能力がなかったの😨。身勝手な韋后に対する不満が爆発して、中宗の甥だった<span class=\"source-bold\">李隆基（のちの玄宗）</span>が挙兵して韋后らを殺害すると、中宗の弟だった父の睿宗を復位させ、父に禅譲を迫って皇帝に即位した。これが<span class=\"source-bold\">玄宗</span>だ。"
      ],
