        "その後、安禄山は息子の安慶緒に殺され、さらに安慶緒を殺した史思明が皇帝を称したけど、彼も息子に殺されるなど反乱軍の足並みが乱れるなか、唐はトルコ系遊牧民のウイグル【回紇】の援軍を得て長安を奪還し、ついに反乱を鎮圧した。"
