      "id": "c03-l10-p04-007",
      "title": "藩鎮の自立と唐の変容",
      "body": [
        "安史の乱は唐の政治や社会を大きく変えてしまった。もう反乱前のような統治には戻れないよ😨。反乱鎮圧のために、唐は内地にも節度使を設置したんだけど、彼らは中央政府の言うことをまるで聞かない。特に、反乱軍から寝返って鎮圧に協力した連中は、節度使の地位を世襲して半独立の<span class=\"source-bold\">藩鎮</span>になった。彼らは集めた税金を中央に送らなかったから、唐は財政難にも苦しんだ。さらに、周辺異民族の侵入も激化したよ。チベットの<span class=\"source-bold\">吐蕃</span>は、乱に乗じて長安を占領したし、反乱鎮圧を支援したウイグルは、見返りに絹馬貿易の利益を得て強くなったんだけど、ときどき唐への反抗を援助する場合もあったんだよ。そのたびに唐はウイグルに金品を贈ってなだめた。そして、則天武后の時代から進んでいた貴族の没落が安史の乱で決定的になった。だって、戦乱で活躍するのは軍人だもん、軍が強いほうがエライ！　こうして唐は支配体制を転換する必要に迫られたってわけね。"
      ],
