      "title": "儒学と仏教研究",
      "body": [
        "中国では前漢以来、儒学が皇帝の専制政治や異民族に対する優位（華夷思想）を裏づける思想だった。もちろん、唐代の中国でも儒学が官学なんだけど、『<span class=\"source-bold\">五経正義</span>』が完成しちゃうと「皇帝の決めた内容はコレ！」っていうふうに解釈が固定され、思想的には停滞した。もはや、儒学は「覚えたらオシマイ」で、新しい議論は発展しなくなった。だから、貴族や頭のいいエリートは「儒学はツマらん😅」と思ったんだ。エリートって今の日本で例えると、東大にトップで合格するような人だから、「趣味が勉強」みたいな優秀な人だもん、難しい内容ほど燃える🔥。だから、仏教の整然とした経典に興味を持ち、「儒学は皇帝が決めた政治思想、仏教は研究する学問」と考えた。こうして、中国では仏教の研究が盛んになったんだ。"
      ],
